import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"快速入门","link":"/guide/getting_started/quick_start/heterogeneous_system_and_programming_model"},{"text":"基于SIMD编程","link":"/guide/getting_started/quick_start/simd_programming/simd_programming"},{"text":"HelloWorld","link":"/guide/getting_started/quick_start/simd_programming/hello_world"}]},"headers":[],"relativePath":"guide/getting_started/quick_start/simd_programming/hello_world.md","filePath":"guide/getting_started/quick_start/simd_programming/hello_world.md","lastUpdated":1787050286000}'),t={name:"guide/getting_started/quick_start/simd_programming/hello_world.md"};function e(c,s,i,o,d,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>Hello World <span id="ZH-CN_TOPIC_0000002523206878"></span></h1><p>本入门示例基于Ascend C SIMD实现Hello World算子，带你快速上手实践，涵盖Device端核函数（Kernel）实现、Host端调用以及编译运行的完整流程，帮助开发者建立整体认知。</p><p>开始前请参考<a href="../../environment_setup.html">环境准备</a>安装所需的CANN软件包，完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/00_introduction/00_quickstart/hello_world/README.md">hello_world</a>。</p><ul><li><p><strong>Hello World功能介绍</strong>：</p><p>在NPU上打印<code>Hello World!!!</code>。</p></li><li><p><strong>Device端核函数（Kernel）实现</strong>：</p><p>后缀名为<code>*.asc</code>的代码文件包含Host端与Device端代码，其Device端部分示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">hello_world</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">printf</span><span class="p">(</span><span class="s">&quot;Hello World!!!</span><span class="se">\\n</span><span class="s">&quot;</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>SIMD算子的核函数（Kernel）需要额外的修饰符，如<a href="../../../programming_guide/language_extension/simd_builtin_keywords.html"><code>__vector__</code></a>修饰符说明该算子仅在向量计算单元上执行。</li></ul></div></li><li><p><strong>Host端代码实现</strong>：</p><p>Host端通过&lt;&lt;&lt;&gt;&gt;&gt;语法糖调用Device端代码片段。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">int</span><span class="w"> </span><span class="nf">main</span><span class="p">(</span><span class="kt">int</span><span class="w"> </span><span class="n">argc</span><span class="p">,</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="k">const</span><span class="o">*</span><span class="w"> </span><span class="n">argv</span><span class="p">[])</span>
<span class="p">{</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">numBlocks</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span>
<span class="w">    </span><span class="n">aclrtStream</span><span class="w"> </span><span class="n">stream</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">;</span>
<span class="w">    </span><span class="n">aclrtCreateStream</span><span class="p">(</span><span class="o">&amp;</span><span class="n">stream</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// Launch kernel &lt;&lt;&lt;numBlocks, dynUBufSize, stream&gt;&gt;&gt;</span>
<span class="w">    </span><span class="c1">// numBlocks : Number of blocks. Default to 8 in this example.</span>
<span class="w">    </span><span class="c1">// dynUBufSize : Dynamic unified buffer size. Default to 0 in this example.</span>
<span class="w">    </span><span class="c1">// stream : Runtime stream. Uses stream created by aclrtCreateStream API in this example.</span>
<span class="w">    </span><span class="n">hello_world</span><span class="o">&lt;&lt;&lt;</span><span class="n">numBlocks</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="p">...</span>
<span class="p">}</span>
</code></pre></div></li><li><p><strong>算子编译与运行</strong>：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>bisheng<span class="w"> </span>hello_world.asc<span class="w"> </span>--npu-arch<span class="o">=</span>dav-2201<span class="w"> </span>-o<span class="w"> </span>demo
./demo
</code></pre></div><p>执行本样例，将打印了核号和<code>Hello World!!!</code>信息。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>该样例支持如下型号： <div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div></li><li>编译选项<code>--npu-arch</code>用于指定NPU架构版本，<code>dav-</code>后为架构版本号，请替换为您实际使用的版本。各AI处理器型号对应的架构版本号请通过<a href="../../../programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">AI处理器型号和 __NPU_ARCH__ 的对应关系</a>查询。</li></ul></div></li></ul><p>如需进一步了解Ascend C的SIMD与SIMT编程模型，请参阅<a href="../../../programming_guide/programming_model/programming_model_overview.html">Ascend C编程模型概述</a>。</p></article></div>`,1)])])}const _=a(t,[["render",e]]);export{g as __pageData,_ as default};
